<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_roles(['pengguna']);require __DIR__.'/../../app/helpers/layout.php';render_start('Dashboard Pengguna','Ruang pribadi pengguna perpustakaan',$u);dashboard_nav('pengguna');render_mid('Halo, '.($u['name']??'Pengguna'),'Selamat datang di Perpustakaan UNCP',$u);
$st=$pdo->prepare("SELECT COUNT(*) FROM books WHERE submitted_by=?");$st->execute([$u['id']]);$myBooks=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT COUNT(*) FROM books WHERE submitted_by=? AND approval_status='menunggu'");$st->execute([$u['id']]);$pendingBooks=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT COUNT(*) FROM repositories WHERE user_id=? AND type='skripsi'");$st->execute([$u['id']]);$myThesis=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT COUNT(*) FROM repositories WHERE user_id=? AND type='skripsi' AND status='menunggu'");$st->execute([$u['id']]);$pendingThesis=(int)$st->fetchColumn();$unread=(int)$pdo->query("SELECT COUNT(*) FROM notifications WHERE user_id=".(int)$u['id']." AND is_read=0")->fetchColumn();
?>
<div class="hero"><h2><?=e($u['name'])?></h2><p>NIM <?=e($u['nim']??'—')?> · <?=e($u['study_program']??'—')?> · Semester <?=e($u['semester']??'—')?></p><a class="btn btn-primary" href="/pengguna/tambah/index.php">Tambah Buku / Skripsi</a></div>
<div class="grid grid-4" style="margin-top:20px"><div class="card stat"><div class="label">Buku Saya</div><div class="num"><?=$myBooks?></div><div class="icon">▣</div></div><div class="card stat"><div class="label">Skripsi Saya</div><div class="num"><?=$myThesis?></div><div class="icon">◫</div></div><div class="card stat"><div class="label">Menunggu Verifikasi</div><div class="num"><?=$pendingBooks+$pendingThesis?></div><div class="icon">⌛</div></div><div class="card stat"><div class="label">Notifikasi Belum Dibaca</div><div class="num"><?=$unread?></div><div class="icon">●</div></div></div>
<div class="grid grid-2" style="margin-top:20px"><div class="card"><div class="toolbar"><b>Pengajuan terbaru</b><a class="btn btn-light" href="/pengguna/riwayat/index.php">Lihat semua</a></div><div style="display:grid;gap:10px;margin-top:14px"><?php $q=$pdo->prepare("SELECT id,title,approval_status AS status,'Buku' AS jenis,created_at FROM books WHERE submitted_by=? UNION ALL SELECT id,title,status AS status,'Skripsi' AS jenis,created_at FROM repositories WHERE user_id=? AND type='skripsi' ORDER BY created_at DESC LIMIT 6");$q->execute([$u['id'],$u['id']]);$rows=$q->fetchAll();foreach($rows as $r):?><div class="submission-card" style="padding:12px;border:1px solid var(--line);border-radius:12px"><div class="toolbar"><b><?=e($r['title'])?></b><span class="badge <?=e(status_class($r['status']))?>"><?=e(status_label($r['status']))?></span></div><small class="muted"><?=e($r['jenis'])?> · <?=e($r['created_at'])?></small></div><?php endforeach;if(!$rows):?><div class="empty">Belum ada pengajuan.</div><?php endif;?></div></div>
<div class="card"><div class="toolbar"><b>Notifikasi</b><span class="badge red"><?=$unread?> baru</span></div><div style="display:grid;gap:10px;margin-top:14px"><?php $n=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 6');$n->execute([$u['id']]);$notes=$n->fetchAll();foreach($notes as $x):?><div style="padding:12px;border:1px solid var(--line);border-radius:12px"><b><?=e($x['title'])?></b><div class="muted" style="font-size:13px;margin-top:4px"><?=e($x['message'])?></div><small class="muted"><?=e($x['created_at'])?></small></div><?php endforeach;if(!$notes):?><div class="empty">Belum ada notifikasi.</div><?php endif;?></div></div></div>
<?php render_end(); ?>
